mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("edges=0-1:0,0-2:1,1-2:0,2-3:1","1"),
        ("edges=0-1:1,1-3:1","2"),
        ("edges=0-1:0,1-3:0","0"),
        ("edges=0-3:1,0-1:0,1-3:0","0"),
        ("edges=0-1:1,1-2:1,2-3:1","3"),
        ("  \nedges=0-1:0,0-2:1,1-2:0,2-3:1\n  ","1"),
        ("\nedges=0-1:1,1-2:1,2-3:1\n","3")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS zero-one-bfs");
}
